import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

detach_template = '''
#### DETACH BEGIN #######
forw mte SetUEContext {ue_id}
forw mte NasConfigEmmDeregister 0
forw mte Activate -1
WAIT FOR "ACTIVATE" TIMEOUT {timeout}
#### DETACH END #######
'''


class DetachScript5G(object):
    """TMA script for detaching a single UE from a 5G cell."""

    def __init__(self, ue_id, timeout=5):
        self.ue_id = ue_id
        self.timeout = timeout

    def __str__(self):
        return detach_template.format(ue_id=self.ue_id,
                                      timeout=self.timeout)

    def __add__(self, other):
        return str(self) + str(other)

    def __radd__(self, other):
        return str(other) + str(self)
